mapper.select:
SELECT COUNT(*) AS callCount, IFNULL(SUM(prompt_tokens), 0) AS totalPromptTokens, IFNULL(SUM(completion_tokens), 0) AS totalCompletionTokens, IFNULL(SUM(total_tokens), 0) AS totalTokens, ROUND(IFNULL(AVG(duration_ms), 0), 2) AS avgDurationMs, IFNULL(MAX(duration_ms), 0) AS maxDurationMs, IFNULL(MIN(duration_ms), 0) AS minDurationMs, SUM(CASE WHEN status = 'success' THEN 1 ELSE 0 END) AS successCount, SUM(CASE WHEN status != 'success' THEN 1 ELSE 0 END) AS failCount, ROUND(IFNULL(SUM(cost_estimate), 0), 6) AS totalCost FROM ai_model_call_log
AND create_time >= #{startDate}
AND create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND user_id = #{userId}
